      "reason": "La résolution 2026-04-125, page 2, accorde la dérogation au 262, rue Westward pour permettre un recul arrière de 0,56 mètre au garage détaché existant."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La résolution 2026-04-126, page 2, approuve à titre de P.I.I.A. une enseigne sur bâtiment et une enseigne sur pylône pour Continental au 307, boulevard Labelle."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "Le dispositif de la résolution 2026-04-127, page 3, approuve à titre de P.I.I.A. la modification des enseignes sur le pylône existant au 400, chemin de la Grande-Côte."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La résolution 2026-04-128, page 3, approuve explicitement à titre de P.I.I.A. le projet d'agrandissement au 266, rue du Bocage."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La résolution 2026-04-129, page 3, approuve à titre de P.I.I.A. l'agrandissement et la construction d'un garage annexé au 338, rue Montview."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "Le dispositif de la résolution 2026-04-130, page 4, approuve à titre de P.I.I.A. la modification des ouvertures au 355, rue Montcalm."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "L'intitulé cité et la résolution 2026-04-131 figurent page 4, où sont approuvés à titre de P.I.I.A. la substitution du revêtement des façades latérales et l'ajout d'une terrasse au toit au 5, chemin de la Grande-Côte."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "Le point 5.3.1, page 4, constate l'avis de motion donné par Marie-Hélène Fortin pour le règlement 1004-01 sur les contributions pour parcs, terrains de jeux et espaces naturels."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "La résolution 2026-04-133, page 5, adopte le projet du règlement 1004-01 et fixe sa consultation publique au 11 mai 2026, étape distincte de l'avis de motion."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "Le point 6.3, page 6, atteste que Stéphanie Nantel donne avis de motion pour le règlement 1015 concernant les propriétés vulnérables aux inondations pluviales."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "Le point 6.3, page 6, précise que Stéphanie Nantel « dépose le projet de règlement », ce qui constitue une unité distincte de l'avis de motion pour le règlement 1015."
    }
  ]
}
